"use client";

import React, { useState, useRef, useEffect } from "react";

interface PasscodeLockProps {
  onUnlock: () => void;
}

const PasscodeLock: React.FC<PasscodeLockProps> = ({ onUnlock }) => {
  const [code, setCode] = useState<string[]>(new Array(6).fill(""));
  const [error, setError] = useState(false);
  const inputs = useRef<(HTMLInputElement | null)[]>([]);

  const correctCode = "122222";

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>, index: number) => {
    const value = e.target.value;
    if (isNaN(Number(value))) return;

    const newCode = [...code];
    newCode[index] = value.substring(value.length - 1);
    setCode(newCode);

    if (value && index < 5) {
      inputs.current[index + 1]?.focus();
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>, index: number) => {
    if (e.key === "Backspace" && !code[index] && index > 0) {
      inputs.current[index - 1]?.focus();
    }
  };

  useEffect(() => {
    if (code.every((digit) => digit !== "")) {
      if (code.join("") === correctCode) {
        onUnlock();
      } else {
        setError(true);
        setTimeout(() => {
          setError(false);
          setCode(new Array(6).fill(""));
          inputs.current[0]?.focus();
        }, 500);
      }
    }
  }, [code, onUnlock]);

  return (
    <div className="flex flex-col items-center justify-center min-h-screen p-4 text-center">
      <div className={`glass p-8 rounded-3xl max-w-md w-full animate-fade-in ${error ? "animate-shake" : ""}`}>
        <h1 className="text-4xl mb-6 text-romantic-pink drop-shadow-sm">
          Enter our secret code 💖
        </h1>
        <p className="mb-8 text-romantic-text/70 italic">“Our special date 💕”</p>
        
        <div className="flex gap-2 justify-center mb-6">
          {code.map((digit, index) => (
            <input
              key={index}
              ref={(el) => { inputs.current[index] = el; }}
              type="text"
              inputMode="numeric"
              maxLength={1}
              value={digit}
              onChange={(e) => handleChange(e, index)}
              onKeyDown={(e) => handleKeyDown(e, index)}
              className="w-12 h-16 text-2xl text-center rounded-xl bg-white/50 border-2 border-romantic-pink/30 focus:border-romantic-pink focus:outline-none transition-all shadow-inner text-romantic-text"
            />
          ))}
        </div>
        
        {error && (
          <p className="text-pink-600 font-medium animate-pulse">
            Oops! That’s not our code 😢
          </p>
        )}
      </div>
    </div>
  );
};

export default PasscodeLock;
