"use client";

import React, { useState, useEffect } from "react";

const RelationshipCounter = () => {
  const [timeTogether, setTimeTogether] = useState({
    years: 0,
    months: 0,
    days: 0,
    hours: 0,
    minutes: 0,
    seconds: 0,
  });

  // Anniversary date matching the passcode 122222 -> Dec 22, 2022
  const startDate = new Date("2022-12-22T00:00:00");

  useEffect(() => {
    const timer = setInterval(() => {
      const now = new Date();
      const diff = now.getTime() - startDate.getTime();

      const seconds = Math.floor((diff / 1000) % 60);
      const minutes = Math.floor((diff / 1000 / 60) % 60);
      const hours = Math.floor((diff / (1000 * 60 * 60)) % 24);
      const daysTotal = Math.floor(diff / (1000 * 60 * 60 * 24));
      
      const years = Math.floor(daysTotal / 365);
      const months = Math.floor((daysTotal % 365) / 30);
      const days = daysTotal % 30;

      setTimeTogether({ years, months, days, hours, minutes, seconds });
    }, 1000);

    return () => clearInterval(timer);
  }, []);

  const Unit = ({ value, label }: { value: number; label: string }) => (
    <div className="flex flex-col items-center bg-white/40 glass p-4 rounded-2xl w-24 h-24 md:w-32 md:h-32 justify-center animate-heartbeat shadow-lg">
      <span className="text-2xl md:text-3xl font-bold text-romantic-pink">{value}</span>
      <span className="text-xs md:text-sm text-romantic-text uppercase tracking-widest">{label}</span>
    </div>
  );

  return (
    <div className="flex flex-col items-center gap-8 py-12 text-center">
      <h3 className="text-3xl md:text-4xl text-romantic-pink font-romantic">Together For</h3>
      <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-4">
        <Unit value={timeTogether.years} label="Years" />
        <Unit value={timeTogether.months} label="Months" />
        <Unit value={timeTogether.days} label="Days" />
        <Unit value={timeTogether.hours} label="Hours" />
        <Unit value={timeTogether.minutes} label="Mins" />
        <Unit value={timeTogether.seconds} label="Secs" />
      </div>
    </div>
  );
};

export default RelationshipCounter;
